--- a/src/price.rs
+++ b/src/price.rs
@@ -7,14 +7,27 @@ pub struct Item {
     pub kop: i64,
 }

-pub fn load(csv: &str) -> Vec<Item> {
-    Vec::new()
+pub fn load(csv: &str) -> Vec<Item> {
+    let mut items: Vec<Item> = csv
+        .lines()
+        .skip(1)
+        .map(parse_row)
+        .filter_map(Result::ok)
+        .collect();
+
+    items.sort_by(|a, b| a.sku.cmp(&b.sku));
+    items
 }

 fn parse_row(line: &str) -> Result<Item, ParseError> {
     let mut cells = line.split(';');

     let sku = cells.next().ok_or(ParseError::Shape)?.to_string();
     let kop = cells.next().ok_or(ParseError::Shape)?.parse()?;

     Ok(Item { sku, kop })
 }
